mkdir -p /tmp/k2search && cat > /tmp/k2search/search.py <<'PY'
from itertools import product, combinations
from functools import lru_cache

# Types
def T(x): return x
TOP=('top',); BOT=('bot',); INT=('int',)
def ARR(a,b): return ('arr',a,b)
def RCD(l,a): return ('rcd',l,a)
def AND(a,b): return ('and',a,b)

types=set([TOP,BOT,INT])
base=list(types)
# iterative generate depth 2
for _ in range(2):
    new=set(types)
    tl=list(types)
    for a,b in product(tl,tl):
        if a[0] in ('top','bot','int') or True:
            new.add(ARR(a,b)); new.add(AND(a,b))
    for l in ('a','b'):
        for a in tl:
            new.add(RCD(l,a))
    types=new
# limit complexity to avoid explosion
def tsize(t):
    if t[0] in ('top','bot','int'): return 1
    if t[0] in ('arr','and'): return 1+tsize(t[1])+tsize(t[2])
    if t[0]=='rcd': return 1+tsize(t[2])
    return 1
types={t for t in types if tsize(t)<=4}
print('types',len(types))

# Expressions
def ekey(e): return repr(e)
ETOP=('top',)
def LIT(i): return ('lit',i)
def ANNO(e,a): return ('anno',e,a)
def EMERGE(e1,e2): return ('merge',e1,e2)
def ERCD(l,e): return ('rcd',l,e)
EABS=('abs',)
exprs=set([ETOP,LIT(0),LIT(1),ANNO(ETOP,INT),ANNO(LIT(0),INT),ANNO(EABS,ARR(TOP,TOP)),EMERGE(LIT(0),LIT(1))])
# close under anno and merge depth
for _ in range(2):
    new=set(exprs)
    el=list(exprs)
    for e in el:
        for a in types:
            if tsize(a)<=3: new.add(ANNO(e,a))
    for e1,e2 in product(el,el):
        if len(new)>4000: break
        new.add(EMERGE(e1,e2))
    exprs=new
    if len(exprs)>5000: break
print('exprs',len(exprs))

# TWell fixpoint
TW=set([TOP,BOT,INT])
changed=True
while changed:
    changed=False
    for t in list(types):
        if t in TW: continue
        ok=False
        if t[0]=='arr': ok=t[1] in TW and t[2] in TW
        elif t[0]=='rcd': ok=t[2] in TW
        elif t[0]=='and': ok=t[1] in TW and t[2] in TW
        if ok: TW.add(t); changed=True
def TWell(t): return t in TW
# ord
ORD=set()
changed=True
while changed:
    changed=False
    for t in types:
        if t in ORD: continue
        ok=False
        if t[0] in ('top','bot','int'): ok=True
        elif t[0]=='arr': ok=(t[2] in ORD)  # lc all
        elif t[0]=='rcd': ok=(t[2] in ORD)
        if ok: ORD.add(t); changed=True
def lc(t): return True
def ordt(t): return t in ORD
# topLike
TL=set()
changed=True
while changed:
    changed=False
    for t in types:
        if t in TL: continue
        ok=False
        if t==TOP: ok=True
        elif t[0]=='and': ok=t[1] in TL and t[2] in TL
        elif t[0]=='arr': ok=TWell(t[1]) and t[2] in TL
        elif t[0]=='rcd': ok=t[2] in TL
        if ok: TL.add(t); changed=True
def topLike(t): return t in TL
def TCWellNil(): return True
def CWellNil(): return True

# spl fixpoint
SPL=set()
changed=True
while changed:
    changed=False
    for t in types:
        for b,c in product(types,types):
            if (t,b,c) in SPL: continue
            ok=False
            if t[0]=='and' and b==t[1] and c==t[2]: ok=True
            elif t[0]=='arr' and b[0]=='arr' and c[0]=='arr' and b[1]==t[1] and c[1]==t[1] and (t[2],b[2],c[2]) in SPL: ok=True
            elif t[0]=='rcd' and b[0]=='rcd' and c[0]=='rcd' and b[1]==t[1] and c[1]==t[1] and (t[2],b[2],c[2]) in SPL: ok=True
            if ok: SPL.add((t,b,c)); changed=True
def SPLQ(a,b,c): return (a,b,c) in SPL

# algo_sub fixpoint (nil)
AS=set()
changed=True
while changed:
    changed=False
    for a,b in product(types,types):
        if (a,b) in AS: continue
        ok=False
        if a==INT and b==INT: ok=True
        elif a==BOT and TWell(b) and ordt(b): ok=True
        elif TWell(a) and ordt(b) and topLike(b): ok=True
        elif a[0]=='and':
            if TWell(a[2]) and ordt(b) and (a[1],b) in AS: ok=True
            elif TWell(a[1]) and ordt(b) and (a[2],b) in AS: ok=True
        elif a[0]=='arr' and b[0]=='arr' and ordt(b[2]) and (b[2],a[2]) in AS and (a[1],b[1]) in AS: ok=True
        elif a[0]=='rcd' and b[0]=='rcd' and a[1]==b[1] and ordt(b[2]) and (a[2],b[2]) in AS: ok=True
        elif b[0]=='and' and SPLQ(b,b[1],b[2]) and (a,b[1]) in AS and (a,b[2]) in AS: ok=True
        if ok: AS.add((a,b)); changed=True
def ASQ(a,b): return (a,b) in AS

# disjoint_axiom
def dax(a,b):
    if a==INT and b[0] in ('arr','rcd'): return True
    if b==INT and a[0] in ('arr','rcd'): return True
    if a[0]=='arr' and b[0] in ('rcd',): return True
    if b[0]=='arr' and a[0] in ('rcd',): return True
    if a[0]=='rcd' and b[0]=='rcd' and a[1]!=b[1]: return True
    return False
DJ=set()
changed=True
while changed:
    changed=False
    for a,b in product(types,types):
        if (a,b) in DJ: continue
        ok=False
        if TWell(a) and TWell(b) and dax(a,b): ok=True
        elif topLike(a) and TWell(b): ok=True
        elif TWell(a) and topLike(b): ok=True
        elif a[0]=='arr' and b[0]=='arr' and TWell(a) and TWell(b) and (a[2],b[2]) in DJ: ok=True
        elif a[0]=='rcd' and b[0]=='rcd' and a[1]==b[1] and (a[2],b[2]) in DJ: ok=True
        elif a[0]=='and' and SPLQ(a,a[1],a[2]) and (a[1],b) in DJ and (a[2],b) in DJ: ok=True
        elif b[0]=='and' and SPLQ(b,b[1],b[2]) and (a,b[1]) in DJ and (a,b[2]) in DJ: ok=True
        if ok: DJ.add((a,b)); changed=True
def disj(a,b): return (a,b) in DJ

# pType prevalue
PT=set()
for e in exprs:
    if e==ETOP: PT.add((e,TOP))
    if e[0]=='lit': PT.add((e,INT))
    if e[0]=='anno': PT.add((e,e[2]))
changed=True
while changed:
    changed=False
    for e in exprs:
        if e[0]=='merge':
            for (a,b) in PT:
                pass
    for e1,a in list(PT):
        for e2,b in list(PT):
            if (e1,e2) not in [None] and ( (('merge',e1,e2),AND(a,b)) not in PT):
                PT.add((('merge',e1,e2),AND(a,b))); changed=True
# Note PT closure maybe huge; restrict exprs
PV=set([ETOP])
for e in exprs:
    if e[0]=='lit': PV.add(e)
    if e[0]=='anno': PV.add(e)
changed=True
while changed:
    changed=False
    for e in exprs:
        if e[0]=='merge' and e[1] in PV and e[2] in PV:
            if e not in PV: PV.add(e); changed=True
def ptype(e,a): return (e,a) in PT
def prevalue(e): return e in PV

# consistent
CS=set()
changed=True
while changed:
    changed=False
    # C_lit
    for i in (0,1):
        if (LIT(i),LIT(i)) not in CS: CS.add((LIT(i),LIT(i))); changed=True
    # C_anno same e any A B
    for e in exprs:
        if e[0]=='anno':
            if (e,e) not in CS: CS.add((e,e)); changed=True
    # C_disjoint pTypes disjoint
    for e1,a in list(PT):
        for e2,b in list(PT):
            if prevalue(e1) and prevalue(e2) and disj(a,b):
                if (e1,e2) not in CS: CS.add((e1,e2)); changed=True
    # mergel/merger
    for e1,e2 in product(exprs,exprs):
        m=('merge',e1,e2)
        for (x,y) in list(CS):
