import re
def names(path):
    out=[]
    for line in open(path):
        m=re.match(r'(?:Lemma|Theorem|Definition|Fixpoint|CoFixpoint|Inductive|Record|Corollary|Fact|Remark)\s+([A-Za-z0-9_\']+)', line)
        if m: out.append(m.group(1))
